 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=max(set(v for row in g for v in row), key=lambda x:sum(r.count(x) for r in g))
    pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v!=bg]
    # Find the color occurring in a diagonal run and continue that run.
    colors={g[r][c] for r,c in pts}
    for color in colors:
        q=[(r,c) for r,c in pts if g[r][c]==color]
        # Continuation is from the endpoint of a same-color diagonal pair.
        for r,c in q:
            for dr,dc in ((1,-1),(1,1)):
                if (r-dr,c-dc) in q and (r+dr,c+dc) not in q:
                    rr,cc=r+dr,c+dc
                    while 0<=rr<h and 0<=cc<w and g[rr][cc]==bg:
                        g[rr][cc]=color
                        rr+=dr; cc+=dc
    return g

